SELECT *
FROM basico.matricula_estudante_serie mes
WHERE mes.id_matricula_discente_serie = 1553744;

SELECT *
FROM ensino.item_abono_frequencia iaf

SELECT iaf.*
FROM ensino.item_abono_frequencia iaf
JOIN ensino.abono_frequencia af ON
af.id_abono_frequencia = iaf.id_abono_frequencia
WHERE af.ativo;
GROUP BY iaf.id_frequencia;

SELECT COALESCE(sum(fa.frequencia), 0) AS faltasTotais, COALESCE(sum(abonos.quantidade_faltas_abonadas), 0) AS apenasAbono, COALESCE(sum(CASE WHEN fa.abonada THEN fa.atual ELSE fa.frequencia END), 0) AS faltasSemAbono
FROM ensino.frequencia_aluno fa
LEFT JOIN ( SELECT iaf.id_frequencia, sum(iaf.quantidade_faltas_abonadas) AS quantidade_faltas_abonadas
FROM ensino.item_abono_frequencia iaf
JOIN ensino.abono_frequencia af ON
af.id_abono_frequencia = iaf.id_abono_frequencia
WHERE af.ativo
GROUP BY iaf.id_frequencia ) abonos ON
abonos.id_frequencia = fa.id_frequencia
JOIN ensino.turma t ON
t.id_turma = fa.id_turma
JOIN basico.turma_serie ts ON
ts.id_turma_serie = t.id_turma_serie
WHERE fa.ativo
AND fa.id_discente = 1386377
AND t.id_turma IN (759517, 759525, 768315, 768317, 768313, 768316, 768314, 768318, 759524, 759519, 759523, 759518, 759521, 759522, 759520);
AND NOT EXISTS (SELECT 1
FROM ensino.interrupcao_escola ie
WHERE ie.id_escola = ts.id_escola
AND fa."data" BETWEEN ie.inicio AND ie.fim
AND ie.ativo);

SELECT SUM(fa.frequencia)
FROM ensino.frequencia_aluno fa
--JOIN ensino.item_abono_frequencia iaf ON iaf.id_frequencia = fa.id_frequencia 
WHERE fa.id_turma IN (768314, 768313, 768318, 768315, 768317, 768316)
AND fa.id_discente = 1386377
--AND fa.ativo;  
